import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"よくある質問","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/faq.md","filePath":"ja/guide/faq.md","lastUpdated":1793173149000}`),a={name:`ja/guide/faq.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="よくある質問" tabindex="-1">よくある質問 <a class="header-anchor" href="#よくある質問" aria-label="Permalink to “よくある質問”">​</a></h1><p>Q: Sudoku とは何ですか？</p><p>A: Sudoku は、論理に基づく定番の数字配置パズルを、現代の Apple デバイス向けに作り直したアプリです。9×9 のグリッドを、各行・各列・各 3×3 ボックスに 1〜9 の数字がちょうど 1 回ずつ入るように埋めます。iPhone、iPad、Mac に対応したユニバーサルアプリで、iCloud 同期にも対応しています。</p><p>Q: 対応しているデバイスを教えてください。</p><p>A: Sudoku は iPhone、iPad、Mac に最適化されたユニバーサルアプリで、ネイティブ操作と精細な Retina ディスプレイ表示に対応しています。iOS/iPadOS 16.0 以降および macOS 15.0（Sequoia）以降が必要です。1 回の購入で対応するすべてのデバイスで使えます。</p><p>Q: Sudoku のダウンロードとインストール方法を教えてください。</p><p>A: Sudoku は App Store からダウンロードできます：<a href="https://apps.apple.com/app/id6793606018" target="_blank" rel="noreferrer">https://apps.apple.com/app/id6793606018</a> — ユニバーサルアプリなので iPhone、iPad、Mac のいずれでも動作します。</p><p>Q: Sudoku にインターネット接続は必要ですか？</p><p>A: 基本的なゲームプレイは 100% オフラインです — パズルを解くのにインターネットは必要ありません。インターネットが必要になる任意の機能には、iCloud 同期（デバイス間の進行状況）、Game Center（リーダーボード／実績）、設定の「More Apps」セクションがあります。</p><p>Q: 広告や App 内課金はありますか？</p><p>A: ありません。Sudoku は完全に広告なしで、ポップアップも App 内課金も中断もありません。純粋にパズルだけに集中できます。</p><p>Q: 利用できる難易度を教えてください。</p><p>A: 初期配置マスの数が異なる 5 つの難易度があります：</p><ul><li><strong>やさしい</strong> — 45 マス（初心者に最適）</li><li><strong>ふつう</strong> — 36 マス（ほどよい手応え）</li><li><strong>むずかしい</strong> — 31 マス（推論テクニックが必要）</li><li><strong>エキスパート</strong> — 27 マス（経験を積んだ方に）</li><li><strong>マスター</strong> — 24 マス（究極の挑戦）</li></ul><p>各パズルはユニークに生成されるため、同じパズルを二度解くことはありません。</p><p>Q: ゲームデータはデバイス間で同期されますか？</p><p>A: はい！iCloud にサインインすると、ゲームのセーブデータ、統計、設定、デイリーチャレンジの進捗が、CloudKit を通じてすべての Apple デバイス間で自動的に同期されます。</p><p>Q: アプリを終了しても進行状況は保存されますか？</p><p>A: はい。現在のゲームは自動的に保存されるので、中断したところからそのまま続けられます。ホーム画面には、進行中のパズルを示す「続きから」カードが表示されます。</p><p>Q: アプリのアップデート方法を教えてください。</p><p>A: App Store のユーザーは自動的にアップデートを受け取ります。手動で確認するには、App Store を開き、アカウント → アップデート のセクションに移動してください。</p><p>Q: バグの報告や機能のリクエストはどうすればよいですか？</p><p>A: プロジェクトリポジトリで issue を作成し、デバイスの種類、iOS／macOS のバージョン、Sudoku のバージョン、再現手順、可能であればスクリーンショットを添えてください。</p><p>Q: 見た目をカスタマイズできますか？</p><p>A: はい！設定から 8 種類の美しいテーマ（クラシック、ミッドナイト、ペーパー、フォレスト、オーシャン、サンセット、ラベンダー、ローズ）を選べます。効果音のオン／オフも切り替えられます。</p><p>Q: 対応している言語はいくつですか？</p><p>A: 25 言語に対応しており、再起動せずに実行中に切り替えられます：英語、中国語（簡体字・繁体字）、日本語、韓国語、フランス語、ドイツ語、スペイン語、イタリア語、ロシア語、ポルトガル語、オランダ語、ベトナム語、タイ語、ヒンディー語、トルコ語、ギリシャ語、フィンランド語、ノルウェー語、デンマーク語、ハンガリー語、インドネシア語、マレー語、ウクライナ語、ドイツ語（スイス）。</p><p>Q: Mac のキーボードショートカットを教えてください。</p><p>A: <code>⌘N</code> で新しいゲーム、<code>⌘Z</code> で元に戻す、<code>⌘1</code> 〜 <code>⌘5</code> で各難易度（やさしい〜マスター）の新しいゲームを開始できます。</p><p>Q: パズルを印刷できますか？</p><p>A: はい！Mac では印刷機能を使い、任意で解答も含めた印刷用パズルをどの難易度でも生成できます。</p><p>さらに回答が必要な場合は、リポジトリで issue を作成するか、ドキュメント全体をご参照ください。</p>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};